# Register only after source/ZIP integrity verification. No release execution or deletion.
param([Parameter(Mandatory)][string]$ReleaseDirectory,[Parameter(Mandatory)][string]$Zip,[Parameter(Mandatory)][string]$RollbackZip)
$ErrorActionPreference='Stop';. (Join-Path $PSScriptRoot 'ArtifactMaintenance.ps1');. (Join-Path $PSScriptRoot 'Distribution.ps1')
$artifacts=Join-Path $script:ArtifactProjectRoot 'artifacts';$folder=Assert-OwnedPath ([IO.Path]::GetFullPath($ReleaseDirectory)) $artifacts;$zipPath=Assert-OwnedPath ([IO.Path]::GetFullPath($Zip)) $artifacts;$rollbackPath=Assert-OwnedPath ([IO.Path]::GetFullPath($RollbackZip)) $artifacts
$meta=Get-Content -LiteralPath (Join-Path $folder distribution.json)-Raw|ConvertFrom-Json;$null=Assert-Distribution $folder SelfContained
$archive=[IO.Compression.ZipFile]::OpenRead($zipPath);try{$entries=@($archive.Entries|Where-Object Name);$files=@(Get-ChildItem -LiteralPath $folder -File -Recurse);if($entries.Count-ne$files.Count){throw 'ZIP file count mismatch'};foreach($entry in $entries){$source=Assert-OwnedPath (Join-Path $folder $entry.FullName) $folder;$stream=$entry.Open();try{$hash=[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($stream))}finally{$stream.Dispose()};if($hash-ne(Get-FileHash -LiteralPath $source).Hash){throw 'ZIP entry mismatch'}}}finally{$archive.Dispose()}
$rollbackArchive=[IO.Compression.ZipFile]::OpenRead($rollbackPath);try{$entry=$rollbackArchive.GetEntry('distribution.json');if($null-eq$entry){throw 'Rollback metadata absent'};$reader=[IO.StreamReader]::new($entry.Open());try{$rollback=$reader.ReadToEnd()|ConvertFrom-Json}finally{$reader.Dispose()}}finally{$rollbackArchive.Dispose()}
$latest=[pscustomobject]@{Version=($meta.BuildVersion-split'\+')[0];Commit=$meta.SourceCommit;Directory=[IO.Path]::GetRelativePath($artifacts,$folder);Zip=[IO.Path]::GetRelativePath($artifacts,$zipPath);Sha256=(Get-FileHash -LiteralPath $zipPath).Hash;Verified=$true;AppExecuted=$false}
$previous=[pscustomobject]@{Version=($rollback.BuildVersion-split'\+')[0];Commit=$rollback.SourceCommit;Zip=[IO.Path]::GetRelativePath($artifacts,$rollbackPath);Sha256=(Get-FileHash -LiteralPath $rollbackPath).Hash;Note='Preserved user-observed prior release; not a claim of all-feature/live verification'}
if($latest.Zip-eq$previous.Zip){throw 'Latest and rollback must differ'}
$index=[pscustomobject]@{Schema=1;CreatedUtc=[DateTimeOffset]::UtcNow;Latest=$latest;Rollback=$previous;Policy='No automatic deletion of executable folders or evidence; cleanup defaults to reviewed dry-run'}
$target=Join-Path $artifacts 'releases.json';if(Test-Path -LiteralPath $target){$null=Assert-OwnedPath $target $artifacts};$temp=Join-Path $artifacts ('release-index-'+[Guid]::NewGuid().ToString('N')+'.tmp');$index|ConvertTo-Json -Depth 6|Set-Content -LiteralPath $temp -Encoding utf8;Move-Item -LiteralPath $temp -Destination $target -Force
$index|ConvertTo-Json -Depth 6
